import THREE from "./init.js";
import TWEEN from "three/examples/jsm/libs/tween.module.js";

// core.js
// Gaussian splats lit by the scene's lights (splat-lighting.js); a manifest
// may set them (AIM3DViewer.viewer.splatLighting).
export const SPLAT_LIGHTING_DEFAULTS = Object.freeze({ enabled: true, strength: 0.8, occlusion: 0.7 });

export const core = {
    clippingPlanes: null,
    materialsFolder: null,
    materialsPropertiesText: null,
    camera: null,
    colors: {},
    intensity: {},
    ambientLight: null,
    cameraLight: null,
    mainCanvas: null,
    noticeContainer: null,
    statusNotice: null,
    gridSize: null,
    dirLightTarget: null,
    lightHelper: null,
    scene: new THREE.Scene(),
    basicGrid: new THREE.Group(),
    axesHelper: new THREE.AxesHelper(),
    cameraCoords: null,
    cameraTweenToken: 0,
    tween: new TWEEN.Tween(),
    controls: null,
    transformControlClippingPlaneY: null,
    transformControlClippingPlaneX: null,
    transformControlClippingPlaneZ: null,
    planeHelpers: null,
    outlineClipping: null,
    sceneBackgroundColor: null,
    distanceGeometry: null,
    planeParams: null,
    clippingFolder: null,
    helperObjects: [],
    isOnline: true, // kept current by connectivity.js
    splatLighting: { ...SPLAT_LIGHTING_DEFAULTS },
    // Files opened from the disk, by their blob: URL (sandbox.js): formats
    // read in pieces (.lif, lif-reader.js) need the File, not its URL.
    localFiles: new Map(),
    // The files of the last archive opened from the disk (extract-helper.js):
    // a TIFF among them may be one slice of a stack of all of them.
    archiveFiles: null,
    // Counts the resets of the scene shown (resetLoadedModelState): a model
    // still loading from before the last one belongs to a scene no longer
    // shown (isStaleModelLoad).
    modelLoadGeneration: 0,
    // Add other shared state here
};

// A model load superseded by a newer scene: it neither joins the scene nor
// moves the camera (loaders.js).
export class StaleModelLoad extends Error {
    constructor() {
        super("Superseded by a newer model load");
        this.name = "StaleModelLoad";
    }
}

// Whether a load started in `generation` was superseded since.
export const isStaleModelLoad = (generation) =>
    Number.isFinite(generation) && generation !== core.modelLoadGeneration;

export const setCore = (key, value) => {
    core[key] = value;
};
